detaileddescription.para:
Usage example: //Declareandcreateanewwindow
sf::Windowwindow(sf::VideoMode({800,600}),"SFMLwindow");

//Limittheframerateto60framespersecond(thisstepisoptional)
window.setFramerateLimit(60);

//Themainloop-endsassoonasthewindowisclosed
while(window.isOpen())
{
//Eventprocessing
while(conststd::optionalevent=window.pollEvent())
{
//Requestforclosingthewindow
if(event->is<sf::Event::Closed>())
window.close();
}

//ActivatethewindowforOpenGLrendering
window.setActive();

//OpenGLdrawingcommandsgohere...

//Endthecurrentframeanddisplayitscontentsonscreen
window.display();
}
